// Paired cases from Appendix D.4: the same mechanism of one system brings memory benefit on one
// question (b) and memory tax on another (t).
const DUAL = [
  {mech: "Focused atomic extraction", sys: "Memory-R2", bench: "LongMemEval-s",
   desc: "Each fact becomes its own short unit. Many facts fit in the context, but small details can fall off.",
   b: {q: "How many properties did I view before making an offer on the townhouse in the Brookside neighborhood?", gold: "4",
       rag: ["1", false], ragSnip: "I actually had a home inspection done on the 3-bedroom <mark>townhouse</mark> I'm buying in the <mark>Brookside</mark> neighborhood …",
       mem: ["4", true], units: ["User recently saw a beautiful 3-bedroom <mark>bungalow</mark> in the Oakwood neighborhood on January 22nd …",
       "User viewed a <mark>1-bedroom condo</mark> on February 10th but the noise from the highway was a deal-breaker"],
       note: "Each viewing becomes its own short fact, so all of them fit in the context."},
   t: {q: "How much discount will I get on my next purchase at FreshMart?", gold: "$5",
       rag: ["$5", true], ragSnip: "I've been trying to shop at FreshMart more often since, you know, 500 points gets me a <mark>$5 discount</mark> on my next purchase.",
       mem: ["$1", false], units: ["2023/05/27 (Sat) 06:17 — User: User has been trying to shop at FreshMart more often due to the <mark>500 points discount offer</mark>"],
       note: "Splitting the turn into one-line facts drops the amount \"$5\"."}},
  {mech: "Multi-hop linking", sys: "PlugMem", bench: "LongMemEval-s",
   desc: "Facts from different sessions get joined into one reasoning note. Great when the reasoning is right.",
   b: {q: "What is the average age of me, my parents, and my grandparents?", gold: "59.6",
       rag: ["information not available", false], ragSnip: "… <mark>my mom is 55 and my dad is 58</mark> …",
       mem: ["59.6", true], units: ["(reasoning note) the user states: \"I'm <mark>32</mark> now\" … \"User's mother is <mark>55</mark> years old and their father is <mark>58</mark> years old.\" … \"My grandma is <mark>75</mark> and my grandpa is <mark>78</mark>\""],
       note: "The note gathers facts from three sessions and computes the answer."},
   t: {q: "How many weeks ago did I attend the 'Summer Nights' festival at Universal Studios Hollywood? (asked on 2023/08/05)", gold: "3 weeks ago",
       rag: ["3 weeks ago", true], ragSnip: "… I <mark>just got back</mark> from an amazing day at Universal Studios Hollywood - we had so much fun at the \"Summer Nights\" festival …",
       mem: ["6 weeks ago", false], units: ["(reasoning note) If the visit was 3 weeks before July 15, and today is 3 weeks after July 15, the total time elapsed since the visit is <mark>3 + 3 = 6 weeks</mark>."],
       note: "Only the note's wrong conclusion reaches the answer model. The raw turn does not."}},
  {mech: "Implicit preference exposure", sys: "OpenViking", bench: "PersonaMem-v2 / LongMemEval-s",
   desc: "A remark made in passing turns into an explicit preference. Sometimes the remark was something else.",
   b: {q: "I'm planning a year-long self-study to go from a curious reader to a solid, working knowledge of two challenging, math-heavy fields …", gold: "a plan for astrophysics and quantum computing",
       rag: ["a generic plan for two math-heavy fields", false], ragSnip: "Selena reads a book with 400 pages. Harry reads a book with 20 fewer than half the number of pages Selena's book has.",
       mem: ["the astrophysics and quantum computing plan", true], units: ["preferences/…/late_night_reading_habits.md: Gets drawn into deep, stimulating articles about <mark>astrophysics</mark> (e.g., black holes) and <mark>quantum computing</mark> (e.g., qubits) late at night."],
       note: "A passing remark becomes an explicit preference line."},
   t: {q: "How much did I spend on each coffee mug for my coworkers?", gold: "$12",
       rag: ["$12", true], ragSnip: "By the way, speaking of gifts, I once spent <mark>$60 on some coffee mugs</mark> for my coworkers, and it was a bit of a splurge, but they loved them.",
       mem: ["$10–20", false], units: ["preferences/user/gift_giving_budget.md: Wants to create a budgeting plan to avoid overspending on gifts … <mark>Spends $10-20 per coworker gift</mark>"],
       note: "The real purchase turns into a budget range taken from the assistant's own suggestion."}},
  {mech: "Temporal anchoring", sys: "SimpleMem", bench: "LongMemEval-s",
   desc: "Relative times like \"three weeks ago\" get pinned to calendar dates. The pin can land on the wrong day.",
   b: {q: "Which task did I complete first, fixing the fence or trimming the goats' hooves?", gold: "fixing the fence",
       rag: ["trimming the goats' hooves", false], ragSnip: "I just fixed that broken fence on the east side of my property <mark>three weeks ago</mark> …",
       mem: ["fixing the fence", true], units: ["The user fixed a broken fence on the east side of the user's property <mark>three weeks prior to 2023-05-25</mark>.",
       "The user successfully trimmed the goats' hooves <mark>two weeks before 2023-05-25</mark> …"],
       note: "Both relative times are anchored to the same date, so the order is explicit."},
   t: {q: "How long did I use my new binoculars before I saw the American goldfinches returning to the area?", gold: "two weeks",
       rag: ["2 weeks", true], ragSnip: "I did manage to sneak in some birding time <mark>a week ago</mark> when I took a walk around my neighborhood after dinner. … I did notice that the American goldfinches …",
       mem: ["3 weeks", false], units: ["The user noted <mark>on 2023-05-20T22:12:00</mark> that American goldfinches are returning to the area",
       "The user reported taking a walk around their neighborhood after dinner <mark>one week prior to 2023-05-20T22:12:00</mark>"],
       note: "The sighting is split from its walk and stamped with the session time."}},
  {mech: "Explicit forgetting", sys: "MAGMA", bench: "PersonaMem-v2",
   desc: "A \"please forget\" request updates the stored state. The rewrite can restate the very thing to forget.",
   b: {q: "Do you have any recommendations for fascinating and informative science-themed films or series that would make a long flight feel shorter?", gold: "a non-science series, since the user asked to forget their interest in science documentaries",
       rag: ["Cosmos, \"since you enjoy science documentaries\"", false], ragSnip: "Since you enjoy science documentaries, you might love 'Cosmos: A Spacetime Odyssey' … [user]: <mark>Please forget</mark> that I enjoy watching science documentaries.",
       mem: ["Ted Lasso", true], units: ["The user <mark>does not want</mark> recommendations for science documentaries."],
       note: "The request becomes a negative preference."},
   t: {q: "I'm planning to redecorate my study with an old-world travel theme. Could you recommend some good spots in Europe or Asia to hunt for authentic vintage prints …?", gold: "a general suggestion, since the user asked to forget that they collect antique maps",
       rag: ["flea markets in Lisbon, paper art stalls in Kyoto", true], ragSnip: "[user]: <mark>Please forget</mark> that I collect antique maps from Europe and Asia. [assistant]: Got it, I'll forget that detail …",
       mem: ["antique maps, \"would fit perfectly with your collection\"", false], units: ["The user now wants this information to be forgotten or ignored by the assistant. • <mark>User collects antique maps from Europe and Asia</mark> (contextual fact being retracted) • collecting antique maps"],
       note: "The request is rewritten into facts that restate the retracted detail."}},
  {mech: "Heterogeneous inputs", sys: "MemOS", bench: "MINT-Eval",
   desc: "Code diffs get described in plain sentences, which semantic search likes. The description can carry a wrong date.",
   b: {q: "At the commit right after the tabulate dependency was first added to requirements.txt, what version of spotipy was pinned in that same file?", gold: "2.12.0",
       rag: ["information not available", false], ragSnip: "[step 50] (2021-02-12) diff --git a/requirements.txt … -spotipy==2.12.0 +spotipy==2.16.1",
       mem: ["2.12.0", true], units: ["On January 31, 2021, the user <mark>added the 'tabulate' library</mark> (version 0.8.7) to the project's requirements.txt file.",
       "On February 12, 2021, the user updated the 'spotipy' library version … <mark>from 2.12.0 to 2.16.1</mark>."],
       note: "Each commit becomes a short dated sentence."},
   t: {q: "In what year did the project first add the compared_methods.py file?", gold: "2016",
       rag: ["2016", true], ragSnip: "[step 3] (2016-11-22T03:39:35Z) … diff --git a/compared_methods.py b/compared_methods.py new file …",
       mem: ["2024", false], units: ["<mark>On January 1, 2024</mark>, the user shared a git diff for the 'trajectory2vec' project … The commit involved deleting files like 'Kmeans_test.py' …"],
       note: "The summary carries a placeholder date in place of the commit time."}},
];

